patch:
--- a/sql/migrations/0002_add_effective_ts_to_stg_orders.sql
+++ b/sql/migrations/0002_add_effective_ts_to_stg_orders.sql
@@ -1,5 +1,5 @@
-- Upstream orders extract now includes an effective_ts column.
-- Add it to stg_orders so the loader's dynamic column list matches the table.
-ALTER TABLE stg_orders ADD COLUMN effective_ts TIMESTAMP;
-COMMENT ON COLUMN stg_orders.effective_ts IS 'Effective timestamp added by upstream extract change, tracked via migration 0002.';
+ALTER TABLE stg_orders ADD COLUMN source_system_ts TIMESTAMP;
+COMMENT ON COLUMN stg_orders.source_system_ts IS 'Source system timestamp from upstream orders extract, tracked via migration 0002.';

--- /dev/null
+++ b/sql/migrations/0003_add_source_system_ts_to_stg_orders.sql
@@ -0,0 +1,3 @@
+-- Upstream orders extract column is actually named source_system_ts (not effective_ts).
+ALTER TABLE stg_orders ADD COLUMN source_system_ts TIMESTAMP;
+COMMENT ON COLUMN stg_orders.source_system_ts IS 'Source system timestamp from upstream extract, added via migration 0003 after confirming actual column name with upstream.';
